def transform(grid):
    grid = [row[:] for row in grid]
    H, W = len(grid), len(grid[0])
    dots = [(r, c, grid[r][c]) for r in range(H) for c in range(W) if grid[r][c] not in (0, 8)]
    for dot in dots:
        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            # check if ray in (dr, dc) enters an enclosure
            cr, cc = dot[0] + dr, dot[1] + dc
            path = []
            hit = False
            while 0 <= cr < H and 0 <= cc < W:
                if grid[cr][cc] == 8:
                    hit = True
                    break
                path.append((cr, cc))
                cr += dr
                cc += dc
            if hit and len(path) > 0:
                # check if there is an 8 nearby to make it an opening
                for pr, pc in path:
                    grid[pr][pc] = dot[2]
                break
    return grid
